import type { components } from './api-types';

/**
 * API types are generated by openapi-typescript from the backend's /api/v1/docs-json (api-types.ts);
 * this file re-exports them under aliases so each service/component's `from './model'` import stays stable.
 * After changing a backend DTO, run `npm run gen:api` to regenerate.
 *
 * StandardResponse<T> is kept hand-written: the generated ApiResult.data is `unknown` (generic erasure),
 * so it cannot replace the frontend's generic envelope (http.post<StandardResponse<Message[]>>).
 */
type S = components['schemas'];

/** Federated media localize status values — the stable wire format (backend serializeBody + MEDIA_STATUS
 *  SSE frame + the attachMediaStatus query field carry these exact strings). A const object so every
 *  reference is `MEDIA_STATUS.READY` (typed + refactor-safe), not a bare literal scattered around.
 *  Mirrors the backend's src/common/media-status.ts. 'ready' = bytes local + authz (URL serves 200);
 *  'failed' = localize failed (URL 4xx, retryable); pending/downloading are durable backend states. */
export const MEDIA_STATUS = {
  READY: 'ready',
  PENDING: 'pending',
  DOWNLOADING: 'downloading',
  FAILED: 'failed',
} as const;
export type MediaStatus = (typeof MEDIA_STATUS)[keyof typeof MEDIA_STATUS];

export type User = S['UserResponseDto'];
export type Message = Omit<
  S['MessageResponseDto'],
  'contentType' | 'mediaStatus'
> & {
  contentType: S['MessageResponseDto']['contentType'];
  /** Immutable author profile selected when this message was committed. */
  profileRev: number;
  /** Federated media localize status (absent = ready). Carried on query-messages rows; one mounted-message
   * service reconciles mount, reconnect and media-status updates. */
  mediaStatus?: MediaStatus;
};
export type MessageCreator = NonNullable<Message['creator']>;

export function messageCreatorKey(creator: MessageCreator): string;
export function messageCreatorKey(creator: null): null;
export function messageCreatorKey(
  creator: MessageCreator | null,
): string | null {
  return creator === null
    ? null
    : JSON.stringify([creator.namespaceId, creator.domain, creator.account]);
}

/** JSON-safe identity persisted inside ClientStateFeed preview bodies. PostgreSQL JSONB cannot store the
 * NUL-separated in-memory creator key, so durable thread previews use an explicit tuple encoding. */
export function messagePreviewSenderKey(creator: MessageCreator): string {
  return JSON.stringify([creator.namespaceId, creator.domain, creator.account]);
}

export function parseUserIdentityKey(key: string): {
  account: string;
  domain: string;
  namespaceId: number;
} | null {
  try {
    const value: unknown = JSON.parse(key);
    if (!Array.isArray(value) || value.length !== 3) return null;
    const [namespaceId, domain, account] = value;
    return Number.isSafeInteger(namespaceId) &&
      (namespaceId as number) >= 0 &&
      typeof domain === 'string' &&
      domain.length > 0 &&
      typeof account === 'string' &&
      account.length > 0
      ? { account, domain, namespaceId: namespaceId as number }
      : null;
  } catch {
    return null;
  }
}
export interface Group {
  id: number;
  account: string;
  name: string;
  ownerId: number;
  avatar: string;
  profileRev: number;
  description: string;
  domain: string;
  namespaceId: number;
  threadId: number;
  createdAt: number;
  updatedAt: number;
  dissolvedAt?: number | null;
  memberCount: number;
  groupMetaFeedId: string;
}

type ConversationItemBase = {
  threadId: number;
  /** Immutable namespace owning this thread's publisher coordinate space. */
  authorityNamespaceId: number;
  role: 'OWNER' | 'ADMIN' | 'MEMBER' | null;
  lastMessageAt: number | null;
  lastMessageSeq?: number | null;
  /** Latest per-thread deletion-log target advertised by the unified content feed. */
  tombstoneEndSeq?: number;
  muted: boolean;
  blocked?: boolean;
  pinned: boolean;
  pinnedAt: number | null;
  alias?: string | null;
  /** P2P only: false after unfriend; history remains readable but sending/calling is disabled. */
  friendshipActive?: boolean;
  conversationState?: 'ACTIVE' | 'READ_ONLY';
  lastReadSeq?: number | null;
  unreadCount: number;
  // Latest-message preview state is derived from message catch-up and the local message cache.
  lastMessagePreviewSeq?: number | null;
  lastMessagePreview?: string | null;
  lastMessageSenderId?: string | null;
  /** Distinct mention kinds among the server's bounded unread sample. */
  mentionUnread: Array<'all' | 'me'>;
  /** Latest group-join application activity; local/client-state metadata used only for list recency. */
  joinRequestAt?: number | null;
};

export type ConversationItem = ConversationItemBase &
  (
    | {
        type: 'P2P';
        peerUser: S['UserResponseDto'];
        group?: never;
      }
    | {
        type: 'GROUP';
        peerUser?: never;
        group: Group;
      }
  );

export type P2PConversationItem = Extract<ConversationItem, { type: 'P2P' }>;
export type GroupConversationItem = Extract<
  ConversationItem,
  { type: 'GROUP' }
>;

type P2PPeerInput = Pick<S['UserResponseDto'], 'id' | 'account' | 'name'> &
  Partial<S['UserResponseDto']>;

/** Construct the canonical local projection for a newly activated, empty P2P thread. */
export function createP2PConversation(
  threadId: number,
  peer: P2PPeerInput,
  overrides: Partial<P2PConversationItem> = {},
): P2PConversationItem {
  const peerUser = {
    avatar: '',
    bio: '',
    isGroup: false,
    domain: 'local',
    namespaceId: 0,
    createdAt: 0,
    updatedAt: 0,
    profileRev: 0,
    isDeleted: false,
    ...peer,
    ...overrides.peerUser,
  };
  return {
    threadId,
    authorityNamespaceId: peerUser.namespaceId,
    type: 'P2P',
    role: null,
    lastMessageAt: null,
    lastMessageSeq: null,
    muted: false,
    blocked: false,
    pinned: false,
    pinnedAt: null,
    alias: null,
    friendshipActive: true,
    conversationState: 'ACTIVE',
    lastReadSeq: null,
    unreadCount: 0,
    mentionUnread: [],
    lastMessagePreview: null,
    lastMessageSenderId: null,
    ...overrides,
    peerUser,
  };
}

type GroupInput = Pick<Group, 'id' | 'account' | 'name' | 'ownerId'> &
  Partial<Group>;

/** Construct the canonical local projection for an empty group thread. */
export function createGroupConversation(
  threadId: number,
  group: GroupInput,
  overrides: Partial<GroupConversationItem> = {},
): GroupConversationItem {
  const groupProfile = {
    avatar: '',
    description: '',
    domain: 'local',
    namespaceId: 0,
    threadId,
    createdAt: 0,
    updatedAt: 0,
    profileRev: 0,
    dissolvedAt: null,
    memberCount: 0,
    groupMetaFeedId: '0',
    ...group,
    ...overrides.group,
  };
  return {
    threadId,
    authorityNamespaceId: groupProfile.namespaceId,
    type: 'GROUP',
    role: null,
    lastMessageAt: null,
    lastMessageSeq: null,
    muted: false,
    blocked: false,
    pinned: false,
    pinnedAt: null,
    alias: null,
    conversationState: 'ACTIVE',
    lastReadSeq: null,
    unreadCount: 0,
    mentionUnread: [],
    lastMessagePreview: null,
    lastMessageSenderId: null,
    ...overrides,
    group: groupProfile,
  };
}

export interface ThreadReadState {
  threadId: number;
  lastReadSeq: number;
  readRevision: number;
  /** 1000 means 1000 or more. */
  unreadCount: number;
  mentionUnread: Array<'all' | 'me'>;
}

export interface ThreadReadDelta {
  readRevision: number;
  items: ThreadReadState[];
}

/**
 * The name to display for a conversation in the chat header + conversation list. A per-user alias (remark)
 * overrides the real name (peer nickname for P2P, group name for GROUP); otherwise the real name is used.
 * Single source of truth — call this everywhere a thread title is rendered so an alias takes effect uniformly.
 */
export function displayThreadName(t: ConversationItem): string {
  if (t.alias) return t.alias;
  return t.type === 'P2P' ? displayUserName(t.peerUser) : t.group.name;
}

/**
 * A user's display name — the nickname (e.g. "Bob"), NOT the login handle. Registration guarantees a
 * non-empty nickname, so there is no account fallback (the handle is never shown as a label). For
 * federated peers are identified by the avatar's globe marker, so the name stays clean. Single source
 * for the name text.
 */
export function displayUserName(u: { name?: string | null }): string {
  return u.name ?? '';
}

/** A user's login address. Local users display the account verbatim; only federated identities append
 *  the server domain with `@` (account@domain). */
export function displayUserAccount(u: {
  account?: string | null;
  domain?: string | null;
}): string {
  const account = u.account ?? '';
  return u.domain && u.domain !== 'local' ? `${account}@${u.domain}` : account;
}

export type PersonalQuotaCategory = 'messages' | 'files' | 'requests';

/** Per-user quota breaker snapshot (msg cnt / file cnt / file total size). `fileBytes` is a decimal string
 *  because file-total-size is a backend bigint. */
export interface PersonalQuotaBreaker {
  tripped: boolean;
  trippedDims: Array<'msg' | 'file' | 'fileBytes'>;
  msg: { count: number; limit: number };
  file: { count: number; limit: number };
  fileBytes: { bytes: string; limit: number };
}

export interface PersonalQuotaState {
  usage: Record<PersonalQuotaCategory, { count: number; limit: number }>;
  breaker: PersonalQuotaBreaker;
  resetAt: number;
}

export type MessageThreadType = ConversationItem['type'];

// Envelope generic (the generated ApiResult.data is unknown and cannot replace this)
export interface StandardResponse<T = unknown> {
  code: number;
  message: string;
  /**
   * Stable i18n key carried by the backend for user-facing statuses that `code` alone cannot disambiguate
   * (e.g. friend-request success variants, all code 0). When present, `translateBizResult` localizes via
   * this and falls back to `message`. Error statuses are localized by numeric `code` (see biz-code.ts).
   */
  messageKey?: string;
  data?: T;
  /** Only paginated endpoints (query-messages) return this: whether an earlier page exists. */
  hasMore?: boolean;
  /** True when this page actually reached the requested truncateSeq boundary. */
  truncated?: boolean;
}

export interface DeletedMessageItem {
  deletionSeq: number;
  threadId: number;
  messageSeq: number;
  type: 'USER_RETRACTION' | 'MODERATION_REMOVAL';
  createdAt: number;
  updatedAt: number;
}
